+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+/**
+ * Real-browser check of the name filter, driven with Drama Finder (Playwright).
+ *
+ * <p>Not part of {@code mvn test}: surefire only picks up {@code *Test} classes.
+ * Run it explicitly with
+ * {@code mvn -o test -Dtest=CustomerListViewBrowserIT -DfailIfNoSpecifiedTests=false}.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Test
+    void filtersInTheBrowser() {
+        GridElement grid = GridElement.get(page);
+        grid.waitForGridToStopLoading();
+        assertEquals(500, grid.getTotalRowCount());
+
+        TextFieldElement filter = new TextFieldElement(
+                page.locator("vaadin-text-field").first());
+        filter.assertPlaceholder("Filter by name");
+        filter.assertValue("");
+
+        filter.setValue("VIR");
+        grid.waitForGridToStopLoading();
+        assertEquals(15, grid.getTotalRowCount());
+        assertTrue(grid.findCell(0, 1).orElseThrow()
+                .getCellContentLocator().innerText().contains("Virtanen"));
+        // Still lazily loaded: the client holds a page, not the whole result set.
+        assertTrue(grid.getRenderedRowCount() <= 15);
+
+        filter.setValue("qvist");
+        grid.waitForGridToStopLoading();
+        assertEquals(14, grid.getTotalRowCount());
+
+        filter.clear();
+        grid.waitForGridToStopLoading();
+        assertEquals(500, grid.getTotalRowCount());
+        assertTrue(grid.getRenderedRowCount() < 500);
+
+        // Deep paging still works: the backend refuses pages over 200 rows, so a
+        // scroll to the end would blow up if the view stopped paging.
+        grid.scrollToEnd();
+        grid.waitForGridToStopLoading();
+        grid.assertRowInView(499);
+    }
+}
